-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Globalisierung > Wettbewerbsvorteile
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Globalisierung Kostenvorteile bei der Produktion erzielen?', 2, '[{"text": "Ja", "correct": true, "because": "Globale Standorte bieten oft niedrigere Kosten"}, {"text": "Nein", "correct": false, "because": "Kostenvorteile sind ein globaler Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöht der Zugang zu internationalen Märkten die Wettbewerbsvorteile eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Größere Märkte bieten mehr Chancen"}, {"text": "Nein", "correct": false, "because": "Globalisierung fördert Vorteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Wettbewerbsvorteile eines IT-Betriebs durch Innovation im globalen Markt gestärkt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Innovation hebt sich global ab"}, {"text": "Nein", "correct": false, "because": "Innovation ist ein Wettbewerbsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Wettbewerbsvorteil eines IT-Betriebs durch Globalisierung unabhängig von der Qualität?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität beeinflusst den globalen Vorteil"}, {"text": "Ja", "correct": false, "because": "Qualität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Bietet die Globalisierung einem IT-Betrieb Vorteile durch größere Skaleneffekte?', 2, '[{"text": "Ja", "correct": true, "because": "Größere Märkte ermöglichen Skaleneffekte"}, {"text": "Nein", "correct": false, "because": "Skaleneffekte sind ein globaler Vorteil"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Wettbewerbsvorteil kann ein IT-Betrieb durch Globalisierung erzielen?', 2, '[{"text": "Kostensenkung durch Outsourcing", "correct": true, "because": "Globale Standorte reduzieren Kosten"}, {"text": "Höhere Steuerlast", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typischer Wettbewerbsvorteil eines IT-Betriebs auf globalen Märkten?', 3, '[{"text": "Zugang zu neuen Technologien", "correct": true, "because": "Globale Märkte bieten Technologiezugriff"}, {"text": "Geringere Marktgröße", "correct": false, "because": "Märkte wachsen"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kosten sinken oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor stärkt die Wettbewerbsvorteile eines IT-Betriebs durch Globalisierung?', 3, '[{"text": "Spezialisierung auf Nischenmärkte", "correct": true, "because": "Nischen bieten globale Vorteile"}, {"text": "Isolation vom Weltmarkt", "correct": false, "because": "Globalisierung fördert Vernetzung"}, {"text": "Weniger Qualität", "correct": false, "because": "Qualität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource kann ein IT-Betrieb global nutzen, um Wettbewerbsvorteile zu erzielen?', 2, '[{"text": "Internationale Talente", "correct": true, "because": "Globale Fachkräfte stärken den Betrieb"}, {"text": "Lokale Steuern", "correct": false, "because": "Kein direkter Vorteil"}, {"text": "Regionale Märkte", "correct": false, "because": "Global ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Wettbewerbsvorteile durch Globalisierung für einen IT-Betrieb?', 3, '[{"text": "Erhöhter Wettbewerbsdruck", "correct": true, "because": "Globale Konkurrenz steigt"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten können sinken"}, {"text": "Einfacher Marktzugang", "correct": false, "because": "Marktzugang kann komplex sein"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Wettbewerbsvorteile kann ein IT-Betrieb durch Globalisierung erzielen?', 4, '[{"text": "Kostensenkung durch Outsourcing", "correct": true, "because": "Globale Standorte reduzieren Kosten"}, {"text": "Zugang zu internationalen Märkten", "correct": true, "because": "Erweitert Kundenbasis"}, {"text": "Höhere lokale Steuern", "correct": false, "because": "Kein Vorteil"}, {"text": "Technologische Innovation", "correct": true, "because": "Globale Vernetzung fördert Innovation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren stärken die Wettbewerbsvorteile eines IT-Betriebs im globalen Markt?', 3, '[{"text": "Niedrige Arbeitskosten", "correct": true, "because": "Globale Standorte bieten Kostenvorteile"}, {"text": "Qualität der Produkte", "correct": true, "because": "Qualität hebt ab"}, {"text": "Isolation vom Markt", "correct": false, "because": "Globalisierung erfordert Vernetzung"}, {"text": "Skaleneffekte", "correct": true, "because": "Größere Märkte senken Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können die Wettbewerbsvorteile einer IT-AG durch Globalisierung mit sich bringen?', 4, '[{"text": "Erhöhter Wettbewerbsdruck", "correct": true, "because": "Globale Konkurrenz steigt"}, {"text": "Kulturelle Unterschiede", "correct": true, "because": "Kann Anpassung erschweren"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten sinken oft"}, {"text": "Komplexere Logistik", "correct": true, "because": "Globale Lieferketten sind komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen kann ein IT-Betrieb global nutzen, um Wettbewerbsvorteile zu sichern?', 3, '[{"text": "Internationale Fachkräfte", "correct": true, "because": "Globale Talente stärken den Betrieb"}, {"text": "Niedrige Produktionskosten", "correct": true, "because": "Globale Standorte senken Kosten"}, {"text": "Lokale Steuern", "correct": false, "because": "Kein direkter Vorteil"}, {"text": "Zugang zu Technologien", "correct": true, "because": "Globale Märkte bieten Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Wettbewerbsvorteile einer IT-AG von einer GmbH im globalen Kontext?', 3, '[{"text": "AG kann leichter Kapital global beschaffen", "correct": true, "because": "Aktien ermöglichen Börsenfinanzierung"}, {"text": "GmbH hat größere Flexibilität", "correct": false, "because": "AG ist flexibler bei Kapital"}, {"text": "AG hat strengere Vorschriften", "correct": true, "because": "AktG ist strenger als GmbHG"}, {"text": "AG nutzt globale Märkte effektiver", "correct": true, "because": "Börsennotierung fördert Globalität"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Globalisierung bietet einem IT-Betrieb Kostenvorteile durch Outsourcing. b) Wettbewerbsvorteile sind unabhängig von der Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenvorteile ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Internationale Märkte erhöhen die Wettbewerbsvorteile eines IT-Betriebs. b) Globalisierung fördert Innovation.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Märkte und Innovation werden gefördert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Skaleneffekte sind ein Wettbewerbsvorteil durch Globalisierung. b) Globalisierung senkt den Wettbewerbsdruck.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skaleneffekte ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein IT-Betrieb kann durch globale Talente Wettbewerbsvorteile erzielen. b) Globalisierung hat keine Nachteile für Wettbewerbsvorteile.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Talente ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Globalisierung erhöht den Wettbewerbsdruck für einen IT-Betrieb. b) Wettbewerbsvorteile durch Globalisierung sind immer kostenneutral.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Druck ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

